local root=app.params['root'];local dir=root..'/outputs/dam-impact';app.fs.makeAllDirectories(dir..'/editable');local file=io.open(dir..'/art.json','r');local art=json.decode(file:read('*a'));file:close();local pages={};local s=Sprite(480,512,ColorMode.RGB)
for f,a in ipairs(art.frames)do if f>1 then s:newEmptyFrame()end;if not pages[a.key]then pages[a.key]=Image{fromFile=root..'/work/dam-impact/candidate/art/'..a.key..'.png'}end;local r=a.rect;s:newCel(s.layers[1],f,Image(pages[a.key],Rectangle(r[1],r[2],r[3],r[4])),Point(0,0));s.frames[f].duration=1/30 end
local tag=s:newTag(1,33);tag.name='white-intensity-0-to-32';s:saveAs(dir..'/editable/white-flash.aseprite');s:close();s=app.open(dir..'/editable/white-flash.aseprite');app.fs.makeAllDirectories(root..'/work/dam-impact/roundtrip')
